from __future__ import annotations

import pytest

from scrappy.infrastructure.scraping.engines.base import EngineFetchOutcome as Outcome
from scrappy.infrastructure.scraping.engines.base import classify_generic

from .conftest import make_page

CLOUDFRONT = (
    "<html><body><h1>ERROR</h1>The request could not be satisfied. "
    "Generated by cloudfront (CloudFront)</body></html>"
)


@pytest.mark.parametrize(
    ("status", "body", "expected"),
    [
        (200, "<html>real</html>", Outcome.OK),
        (200, '{"data": []}', Outcome.OK),
        (400, "bad", Outcome.OK),
        (403, CLOUDFRONT, Outcome.BLOCKED),
        (403, "plain", Outcome.BLOCKED),
        (429, "slow down", Outcome.BLOCKED),
        (404, "nope", Outcome.NOT_FOUND),
        (410, "gone", Outcome.NOT_FOUND),
        (500, "oops", Outcome.TRANSIENT),
        (502, "bad gateway", Outcome.TRANSIENT),
        (503, "maintenance", Outcome.TRANSIENT),
        (503, "<title>Just a moment...</title>", Outcome.BLOCKED),
        (200, "<title>Just a moment...</title><script>cf-chl-opt</script>", Outcome.BLOCKED),
        (200, CLOUDFRONT, Outcome.BLOCKED),
        (200, "<html>Attention Required! | Cloudflare</html>", Outcome.BLOCKED),
    ],
)
def test_classify_generic(status: int, body: str, expected: Outcome) -> None:
    assert classify_generic(make_page(status, body)) is expected


def test_large_page_mentioning_marker_is_ok() -> None:
    body = "x" * 60_000 + " cf-chl "
    assert classify_generic(make_page(200, body)) is Outcome.OK
